+    __m512i d1 = _mm512_unpackhi_epi16(r0, r1);          \
+    r0 = _mm512_shuffle_i32x4(d0, d1, 0x88);             \
+    r1 = _mm512_shuffle_i32x4(d0, d1, 0xdd);             \
+    (ap) = _mm512_shuffle_i32x4(r0, r1, 0x88);           \
+    (bp) = _mm512_shuffle_i32x4(r0, r1, 0xdd);           \
